```json
{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT date_trunc('minute', time) AS m, round(avg(value),3) AS geo_cpu_cores FROM abnormal_metrics WHERE service_name='geo' AND metric='container.cpu.usage' GROUP BY 1 ORDER BY 1",
          "claim": "Geo container CPU rises from about 1.0 to about 1.6 cores from 12:35 and stays pinned flat through 12:40."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, round(avg(value),4) AS avg_cpu_cores FROM normal_metrics WHERE metric='container.cpu.usage' AND service_name='geo' GROUP BY 1",
          "claim": "In the normal period geo container CPU averages about 0.003 cores, so the abnormal level is roughly 500 times higher."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, round(avg(value),2) AS abn_avg FROM abnormal_metrics WHERE service_name='geo' AND metric IN ('container.memory.rss','k8s.pod.memory.rss') GROUP BY 1,2",
          "claim": "Geo memory RSS rises about 40 percent (about 15 MB to 21 MB) alongside the CPU spike."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, span_name, count(*) AS n, round(quantile_cont(duration,0.95)/1e6,2) AS p95_ms FROM abnormal_traces WHERE span_name='geo.Geo/Nearby' GROUP BY 1,2,3",
          "claim": "search issues geo.Geo/Nearby client calls during the incident, but their p95 latency (about 0.5 ms) matches normal, so the propagation is weak in the spans."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, span_name, count(*) AS n, round(quantile_cont(duration,0.95)/1e6,2) AS p95_ms FROM abnormal_traces WHERE span_name='search.Search/Nearby' GROUP BY 1,2,3",
          "claim": "frontend's client calls to search.Search/Nearby run at about 10.5 ms p95, matching normal, so the search-to-frontend edge shows no measurable change."
        }
      ]
    }
  ]
}
```

